from pathlib import Path
root=Path(__file__).resolve().parent.parent
p=root/'src/learning.js'
s=p.read_text(encoding='utf-8')
def replacefun(name,nextname,body):
 global s
 a=s.index('function '+name+'(');b=s.index('function '+nextname+'(',a)
 s=s[:a]+body+'\n'+s[b:]
replacefun('classify','seasons',r'''function classify(s,u){
 const checked=u.ruleCheck?.key===classificationKey(s)?u.ruleCheck:null;
 const labels=s.rule==='edge'?['큰 톱니가 보여','큰 톱니가 없어']:['가늘고 길쭉해','다른 모양이야'];
 return layout(`<div class="learning-tabs">${button('① 큰 톱니로 나누기','rule','edge',s.rule==='edge')}${button('② 모양으로 다시 나누기','rule','narrow',s.rule==='narrow')}</div><div class="classify-leaves">${PLANTS.map(p=>`<button class="plant-card ${u.selected===p.id?'selected':''}" data-action="select-plant" data-id="${p.id}" draggable="true" data-drag="${p.id}" aria-pressed="${u.selected===p.id}">${leafArt(p.id)}<strong>${p.name}</strong><small>${s.groups[p.id]?labels[s.groups[p.id]==='yes'?0:1]:'아직 놓지 않았어'}</small></button>`).join('')}</div><p class="direct-hint">잎을 끌어 놓아 봐. 잎 → 상자 순서로 눌러도 돼.</p><div class="sort-bins">${['yes','no'].map((g,i)=>`<button class="sort-bin" data-action="assign-group" data-id="${g}" data-drop="group"><strong>${labels[i]}</strong><div>${PLANTS.filter(p=>s.groups[p.id]===g).map(p=>`<span class="placed-label">${p.name}</span>`).join('')||'이곳에 잎 놓기'}</div></button>`).join('')}</div><div class="center">${button('내 분류 확인하기','check-rule')}</div>${checked?`<p class="rule-result" role="status">${checked.valid?'세 잎 모두 기준에 맞아!':`아직 안 놓은 잎 ${checked.missing}개 · 기준과 다른 잎 ${checked.conflicts}개`}</p>`:''}${checked?.valid?`<div class="reason-cards"><p>어떤 관찰을 보고 나누었어?</p>${PLANTS.map(p=>button(`${p.name} · ${s.rule==='edge'?p.edgeText:p.shape}`,'classification-proof',p.id,s.classificationEvidence[s.rule]===p.id)).join('')}</div>`:''}`,panel('표본 서랍 복구',`${['edge','narrow'].map(r=>row(classificationComplete(s,r),r==='edge'?'큰 톱니 기준':'잎 모양 기준')).join('')}<p>기준을 바꾸면 같은 잎의 자리가 달라져. 두 서랍의 기록을 완성해 줘.</p>`));
}''')
replacefun('seasons','seasonsCompare',r'''function seasons(s){
 return layout(`${plantTabs([{id:'cherry',name:'벚나무'},{id:'sowthistle',name:'씀바귀'}],'season-plant',s.seasonPlant)}<div class="season-scene"><div id="season-art">${seasonArt(s.seasonPlant,s.season,s.underground)}</div><span id="season-label" class="scene-badge">${seasonName(s.season)}</span>${button(s.underground?'땅속 닫기':'땅속 보기','underground','',s.underground)}</div><div class="timeline"><label for="season-range" class="direct-hint">시간 손잡이를 움직여 같은 식물을 따라가 봐.</label><input id="season-range" type="range" min="0" max="3" step="1" value="${[1,2,3,0].indexOf(s.season)}"><div>${[1,2,3,0].map(n=>button(seasonName(n),'season',String(n),s.season===n)).join('')}</div></div><p class="season-caption" id="season-caption">${seasonText(s.seasonPlant,s.season)}</p>${button(s.seasonalRecords.includes(`${s.seasonPlant}:${s.season}`)?'📷 다시 찍기':'📷 이 모습 찍기','record-season')}`,panel('끊긴 계절 기록',`${['cherry','sowthistle'].map(p=>`<section><strong>${name(p)}</strong>${[3,0].map(n=>row(!!s.seasonPhotos[`${p}:${n}`],seasonName(n))).join('')}</section>`).join('')}<p>두 식물의 겨울과 다음 봄을 남겨 줘. 땅속에는 무엇이 남아 있을까?</p>`));
}''')
replacefun('seasonsCompare','experiment',r'''function seasonsCompare(s){
 return layout(`${plantTabs([{id:'cherry',name:'벚나무'},{id:'sowthistle',name:'씀바귀'}],'season-plant',s.seasonPlant)}<p class="direct-hint">네가 찍은 겨울과 다음 봄 사진을 한 장씩 골라 이어 줘.</p><div class="season-pair">${[3,0].map(n=>{const key=`${s.seasonPlant}:${n}`,has=!!s.seasonPhotos[key],linked=s.linkedEvidence.includes(key);return `<button class="evidence-photo ${linked?'linked':''}" data-action="season-evidence" data-id="${n}" aria-pressed="${linked}" ${has?'':'disabled'}><strong>${seasonName(n)} ${linked?'✓':''}</strong>${has?seasonArt(s.seasonPlant,n,s.seasonPhotos[key]?.underground===true):'<p>앞 활동에서 이 모습을 남겨 줘.</p>'}</button>`;}).join('')}</div>${seasonEvidenceReady(s)?`<div class="evidence-bridge">겨울에 살아 있던 부분 → 다음 봄 새로 자란 부분</div><div class="reason-cards"><p>두 기록이 보여 주는 것은?</p>${button(s.seasonPlant==='cherry'?'같은 나무에 새잎과 꽃이 나왔어요':'살아 있던 뿌리에서 새싹이 나왔어요','season-explain','growth',s.seasonExplained.includes(s.seasonPlant))}${button('식물이 모두 사라졌어요','season-explain','gone')}</div>`:''}`,panel('계절을 이은 증거',`${['cherry','sowthistle'].map(p=>row(s.seasonExplained.includes(p),name(p)+'의 겨울과 다음 봄')).join('')}<p>겨울에 모두 없어진 걸까? 살아 있던 부분에서 다시 자라는지 살펴봐.</p>`));
}''')
s=s.replace("${plantTabs(PLANTS,'specimen',p.id)}", "<div class=\"specimen-tray\">${PLANTS.map(item=>`<button class=\"specimen-pick ${p.id===item.id?'selected':''}\" data-action=\"specimen\" data-id=\"${item.id}\" aria-pressed=\"${p.id===item.id}\">${leafArt(item.id)}<strong>${item.name}</strong></button>`).join('')}</div>")
