s=s.replace("const tools=n===0?", "const predict=`<div class=\"prediction\"><p>물속에서 누르면 어떻게 될까?</p>${button('공기 방울이 나올 것 같아','experiment-predict','bubbles',s.experiment.prediction==='bubbles')}${button('아무것도 안 나올 것 같아','experiment-predict','none',s.experiment.prediction==='none')}</div>`;\n  const tools=n===0?")
s=s.replace("scene+`<div class=\"center\">${tools}</div>","scene+`${n<4?predict:`<p class=\"rule-result\">${s.experiment.prediction==='none'?'예상과 달랐어! ':s.experiment.prediction==='bubbles'?'예상처럼 ':''}누른 잎자루에서 공기 방울이 나왔어.</p>`}<div class=\"center\">${tools}</div>")
a=s.index('function habitats(');b=s.index('function garden(',a)
s=s[:a]+r'''function habitats(s,u){const p=HABITAT_PLANTS.find(p=>p.id===u.selected)||HABITAT_PLANTS[0],fact=HABITAT_FACTS[p.id];return layout(`${plantTabs(HABITAT_PLANTS,'select-plant',p.id)}<div class="habitat-focus">${plantArt(p.id)}<p><small>${fact.source}</small><br>${fact.feature}</p></div><p class="chain-title">① 어디에서 살까?</p><div class="environment-cards">${Object.entries(HABITATS).map(([id,n])=>button(`${icon(id==='water'?'drop':id==='dry'?'sun':'leaf')}<strong>${n}</strong><small>${environmentText[id]}</small>`,'habitat',id,s.habitats[p.id]===id)).join('')}</div>${s.habitats[p.id]?`<div class="reason-cards"><p>② 어떤 특징이 보였어?</p>${Object.entries(HABITAT_FACTS).map(([id,f])=>button(f.feature,'habitat-feature',id,s.habitatFeatures[p.id]===id)).join('')}</div>`:''}${s.habitatFeatures[p.id]?`<div class="reason-cards"><p>③ 그곳에서 어떻게 도움이 될까?</p>${Object.entries(HABITAT_FACTS).map(([id,f])=>button(f.life,'habitat-answer',id,s.reasons[p.id]===id)).join('')}</div>`:''}`,panel('환경 → 특징 → 생활',HABITAT_PLANTS.map(p=>row(habitatChain(s,p.id)&&s.reasons[p.id]===p.id,p.name)).join('')+'<p>연결한 기록은 다음 정원에서 식물의 자리를 정할 때 쓰여.</p>'));}
''' + s[b:]
s=s.replace('<div class="garden-frame">${grid()}</div>','<div class="garden-frame" data-spatial="garden">${grid()}</div><p class="direct-hint">${place?\'식물을 골라 땅에 놓아 줘.\':\'땅 위를 쓸어서 물가·풀밭·건조 구역을 만들어 봐.\'}</p>')
s=s.replace("'<p class=\"center\">上で植物を選んで</p>'.replace('上で植物を選んで','위에서 식물을 고르고, 심을 땅을 눌러 줘.')","'<p class=\"center\">위에서 식물을 고르고, 심을 땅을 눌러 줘.</p>'")
p.write_text(s,encoding='utf-8')
